using System;using System.Security.Cryptography;using System.Text;using CapybaraGame.Core;
namespace CapybaraGame.Puzzle{public static class PuzzleFingerprint{
public static string Compute(PuzzleDefinition p){var sizes=new int[p.regionCount];foreach(int z in p.regions)sizes[z]++;Array.Sort(sizes);int boundary=0;for(int r=0;r<p.rows;r++)for(int c=0;c<p.columns;c++){int z=p.RegionAt(r,c);if(r+1<p.rows&&p.RegionAt(r+1,c)!=z)boundary++;if(c+1<p.columns&&p.RegionAt(r,c+1)!=z)boundary++;}string raw=p.rows+"x"+p.columns+"|"+string.Join(",",sizes)+"|"+boundary+"|"+string.Join(",",p.solution);using(var sha=SHA256.Create()){var b=sha.ComputeHash(Encoding.UTF8.GetBytes(raw));var s=new StringBuilder(16);for(int i=0;i<8;i++)s.Append(b[i].ToString("x2"));return s.ToString();}}
public static bool StructurallySimilar(PuzzleDefinition a,PuzzleDefinition b){if(a==null||b==null||a.rows!=b.rows||a.columns!=b.columns||a.regionCount!=b.regionCount)return false;var x=Sizes(a);var y=Sizes(b);Array.Sort(x);Array.Sort(y);int d=0;for(int i=0;i<x.Length;i++)d+=Math.Abs(x[i]-y[i]);return d<=Math.Max(2,a.CellCount/10);}
static int[] Sizes(PuzzleDefinition p){var a=new int[p.regionCount];foreach(int z in p.regions)a[z]++;return a;}}}